<template>
  <div class="monitor-page page-content">
    <header class="heading"><div><span class="eyebrow">TOOLS / DATA MONITOR</span><h1 class="page-title">数据监控</h1><p>设定行情条件，在触发时通过已配置的飞书机器人通知。</p></div><el-button type="primary" @click="openCreate">新建监控任务</el-button></header>
    <section class="stats"><article><span>运行中任务</span><strong>{{ tasks.filter(x => x.enabled).length }}</strong><small>共 {{ tasks.length }} 个任务</small></article><article><span>监控对象</span><strong>{{ new Set(tasks.map(x => x.symbol)).size }}</strong><small>OKX 现货</small></article><article><span>今日通知</span><strong>{{ todayCount }}</strong><small>触发提醒与定时汇报</small></article><article><span>推送成功率</span><strong>{{ successRate }}</strong><small>最近 100 条事件</small></article></section>
    <section class="panel"><el-tabs v-model="tab">
      <el-tab-pane name="tasks" :label="`监控任务  ${tasks.length}`">
        <div class="toolbar"><div class="filters"><el-input v-model="keyword" clearable placeholder="搜索任务或交易对象" style="width:240px"/><el-select v-model="status" style="width:120px"><el-option label="全部状态" value="all"/><el-option label="运行中" value="running"/><el-option label="已暂停" value="paused"/></el-select></div><el-button text @click="loadTasks">刷新数据</el-button></div>
        <el-table v-loading="loading" :data="filteredTasks" empty-text="暂无监控任务">
          <el-table-column label="任务 / 交易对象" min-width="210"><template #default="{ row }"><div class="stack"><strong>{{ row.name }}</strong><small>{{ row.symbol }} · {{ row.exchange }}</small></div></template></el-table-column>
          <el-table-column label="触发条件" min-width="190"><template #default="{ row }"><div class="stack"><span>{{ row.ruleName }}</span><small>{{ conditionText(row) }}</small></div></template></el-table-column>
          <el-table-column label="当前值" min-width="130"><template #default="{ row }"><b class="number">{{ row.lastValue == null ? '—' : formatValue(row.lastValue, row.metric) }}</b></template></el-table-column>
          <el-table-column label="推送到" min-width="150"><template #default="{ row }"><div class="stack"><span>{{ row.channelName }}</span><small>{{ row.templateName }}</small></div></template></el-table-column>
          <el-table-column label="最近触发" min-width="150"><template #default="{ row }"><span class="muted">{{ formatTime(row.lastTriggeredAt) }}</span></template></el-table-column>
          <el-table-column label="状态" width="90" align="center"><template #default="{ row }"><el-switch :model-value="row.enabled" :loading="togglingId === row.id" @change="toggleTask(row, Boolean($event))"/></template></el-table-column>
          <el-table-column label="操作" width="160" align="right"><template #default="{ row }"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-dropdown trigger="click"><el-button link>更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="duplicateTask(row)">复制任务</el-dropdown-item><el-dropdown-item @click="showEvents(row)">触发记录</el-dropdown-item><el-dropdown-item divided @click="removeTask(row)">删除任务</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column>
        </el-table>
      </el-tab-pane>
      <el-tab-pane name="rules" :label="`规则库  ${rules.length}`"><div class="section-head"><div><h2>监控规则</h2><p>预设阈值、定时汇报和区间浮动，也可自定义。</p></div><el-button @click="ruleDialog = true">新建自定义规则</el-button></div><div class="cards rules"><article v-for="(rule,index) in rules" :key="rule.id"><div class="card-meta"><span>RULE {{ String(index + 1).padStart(2,'0') }}</span><span>{{ rule.system ? '系统预设' : '自定义' }}</span></div><h3>{{ rule.name }}</h3><p>{{ rule.description }}</p><div class="expression">{{ conditionText(rule) }}</div><footer><span>已用于 {{ rule.usage }} 个任务</span><div><el-button link type="primary" @click="useRule(rule)">使用规则</el-button><el-button v-if="!rule.system" link @click="removeRule(rule)">删除</el-button></div></footer></article></div></el-tab-pane>
      <el-tab-pane name="templates" :label="`推送模板  ${templates.length}`"><div class="section-head"><div><h2>消息模板</h2><p>发送时自动填入监控对象、当前值和时间。</p></div><el-button @click="templateDialog = true">新建自定义模板</el-button></div><div class="cards templates"><article v-for="item in templates" :key="item.id"><div class="card-meta"><span>{{ item.system ? '系统预设' : '自定义' }}</span><span>{{ item.messageType === 'card' ? '消息卡片' : '文本消息' }}</span></div><h3>{{ item.name }}</h3><div class="template-preview"><b>{{ item.title }}</b><p>{{ item.content }}</p></div><footer><span>已用于 {{ item.usage }} 个任务</span><el-button v-if="!item.system" link @click="removeTemplate(item)">删除</el-button></footer></article></div></el-tab-pane>
    </el-tabs></section>
    <el-drawer v-model="taskDrawer" :title="editingId ? '编辑监控任务' : '新建监控任务'" size="min(620px, 100%)" destroy-on-close>
      <div class="steps"><span v-for="n in 3" :key="n" :class="{current:step===n}">{{ String(n).padStart(2,'0') }}　{{ ['监控对象','触发规则','推送策略'][n-1] }}</span></div>
      <div v-if="step===1" class="step"><h3>监控对象</h3><p>一个任务监控一个交易对，可独立设置频率。</p><el-form label-position="top"><el-form-item label="任务名称" required><el-input v-model="form.name" maxlength="100" placeholder="例如：BTC 价格突破"/></el-form-item><div class="form-grid"><el-form-item label="交易所"><el-select v-model="form.exchange"><el-option label="OKX 现货" value="OKX"/></el-select></el-form-item><el-form-item label="交易对象" required><el-select v-model="form.symbol" filterable remote :remote-method="searchSymbols" :loading="symbolLoading" placeholder="搜索交易对"><el-option v-for="item in symbols" :key="item" :label="item" :value="item"/></el-select></el-form-item></div><el-form-item label="检测频率"><el-radio-group v-model="form.frequencySeconds"><el-radio-button :value="10">10 秒</el-radio-button><el-radio-button :value="60">1 分钟</el-radio-button><el-radio-button :value="300">5 分钟</el-radio-button></el-radio-group></el-form-item></el-form><div class="subtle-box">当前选择 <b>{{ form.symbol }} · OKX</b></div></div>
      <div v-else-if="step===2" class="step"><h3>触发规则</h3><p>选择预设规则后，可单独调整当前任务条件。</p><div class="rule-picks"><button v-for="rule in rules" :key="rule.id" type="button" :class="{selected:form.ruleId===rule.id}" @click="selectRule(rule)"><b>{{ rule.name }}</b><small>{{ rule.description }}</small></button></div><div class="condition-box"><b>当前任务条件</b><el-form label-position="top"><el-form-item label="规则类型"><el-segmented v-model="form.ruleType" :options="ruleTypeOptions"/></el-form-item><div v-if="form.ruleType==='threshold'" class="form-grid three"><el-form-item label="指标"><el-select v-model="form.metric"><el-option label="最新价格" value="price"/><el-option label="24h 涨跌幅" value="change"/><el-option label="24h 成交额" value="volume"/><el-option label="RSI(14)" value="rsi"/></el-select></el-form-item><el-form-item label="条件"><el-select v-model="form.operator"><el-option label="大于" value=">"/><el-option label="小于" value="<"/><el-option label="向上穿越" value="cross_up"/><el-option label="向下穿越" value="cross_down"/></el-select></el-form-item><el-form-item label="阈值"><el-input-number v-model="form.threshold" :controls="false"/></el-form-item></div><div v-else-if="form.ruleType==='scheduled'" class="form-grid three"><el-form-item label="每日开始"><el-input v-model="form.startTime" type="time"/></el-form-item><el-form-item label="每日结束"><el-input v-model="form.endTime" type="time"/></el-form-item><el-form-item label="每隔多少分钟"><el-input-number v-model="form.reportIntervalMinutes" :min="1" :max="1440" :controls="false"/></el-form-item></div><div v-else class="form-grid movement-grid"><el-form-item label="滚动窗口（分钟）"><el-input-number v-model="form.windowMinutes" :min="1" :max="1440" :controls="false"/></el-form-item><el-form-item label="浮动方向"><el-select v-model="form.movementDirection"><el-option label="上涨或下跌" value="either"/><el-option label="只看上涨" value="up"/><el-option label="只看下跌" value="down"/></el-select></el-form-item><el-form-item label="幅度单位"><el-select v-model="form.movementUnit"><el-option label="百分比 %" value="percent"/><el-option label="金额 USDT" value="amount"/></el-select></el-form-item><el-form-item label="达到幅度"><el-input-number v-model="form.threshold" :min="0.000001" :controls="false"/></el-form-item></div></el-form><span>{{ conditionText(form) }}</span></div></div>
      <div v-else class="step"><h3>推送策略</h3><p>选择已启用的飞书机器人与消息模板。</p><el-form label-position="top"><el-form-item label="推送渠道" required><el-select v-model="form.pushConfigId" placeholder="选择机器人"><el-option v-for="item in enabledChannels" :key="item.id" :label="`${item.name} · ${item.botType==='app'?'应用机器人':'自定义机器人'}`" :value="item.id"/></el-select></el-form-item><div v-if="!enabledChannels.length" class="notice">暂无已启用的机器人，请先在「系统管理 → 消息推送」配置。</div><el-form-item label="消息模板" required><el-select v-model="form.templateId"><el-option v-for="item in templates" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><div v-if="form.ruleType!=='scheduled'" class="form-grid"><el-form-item label="重复提醒冷却"><el-select v-model="form.cooldownSeconds"><el-option label="5 分钟" :value="300"/><el-option label="15 分钟" :value="900"/><el-option label="1 小时" :value="3600"/></el-select></el-form-item><el-form-item label="恢复通知"><div class="switch-row">恢复正常时通知<el-switch v-model="form.recoveryNotice"/></div></el-form-item></div></el-form><div class="summary"><b>任务摘要</b><dl><div><dt>交易对象</dt><dd>{{ form.symbol }} · OKX</dd></div><div><dt>触发条件</dt><dd>{{ conditionText(form) }}</dd></div><div><dt>推送渠道</dt><dd>{{ enabledChannels.find(x=>x.id===form.pushConfigId)?.name||'未选择' }}</dd></div><div><dt>消息模板</dt><dd>{{ templates.find(x=>x.id===form.templateId)?.name||'未选择' }}</dd></div></dl></div></div>
      <template #footer><div class="drawer-actions"><el-button @click="taskDrawer=false">取消</el-button><div><el-button v-if="step>1" @click="step--">上一步</el-button><el-button type="primary" :loading="saving" @click="nextStep">{{ step===3?(editingId?'保存修改':'创建并启用'):'下一步' }}</el-button></div></div></template>
    </el-drawer>
    <el-dialog v-model="ruleDialog" title="新建自定义规则" width="min(620px, 95vw)"><el-form label-position="top"><el-form-item label="规则名称" required><el-input v-model="ruleForm.name"/></el-form-item><el-form-item label="说明"><el-input v-model="ruleForm.description"/></el-form-item><el-form-item label="规则类型"><el-segmented v-model="ruleForm.ruleType" :options="ruleTypeOptions"/></el-form-item><div v-if="ruleForm.ruleType==='threshold'" class="form-grid three"><el-form-item label="指标"><el-select v-model="ruleForm.metric"><el-option label="最新价格" value="price"/><el-option label="24h 涨跌幅" value="change"/><el-option label="24h 成交额" value="volume"/><el-option label="RSI(14)" value="rsi"/></el-select></el-form-item><el-form-item label="条件"><el-select v-model="ruleForm.operator"><el-option label="大于" value=">"/><el-option label="小于" value="<"/><el-option label="向上穿越" value="cross_up"/><el-option label="向下穿越" value="cross_down"/></el-select></el-form-item><el-form-item label="阈值"><el-input-number v-model="ruleForm.threshold" :controls="false"/></el-form-item></div><div v-else-if="ruleForm.ruleType==='scheduled'" class="form-grid three"><el-form-item label="每日开始"><el-input v-model="ruleForm.startTime" type="time"/></el-form-item><el-form-item label="每日结束"><el-input v-model="ruleForm.endTime" type="time"/></el-form-item><el-form-item label="间隔（分钟）"><el-input-number v-model="ruleForm.reportIntervalMinutes" :min="1" :max="1440" :controls="false"/></el-form-item></div><div v-else class="form-grid movement-grid"><el-form-item label="窗口（分钟）"><el-input-number v-model="ruleForm.windowMinutes" :min="1" :max="1440" :controls="false"/></el-form-item><el-form-item label="方向"><el-select v-model="ruleForm.movementDirection"><el-option label="上涨或下跌" value="either"/><el-option label="只看上涨" value="up"/><el-option label="只看下跌" value="down"/></el-select></el-form-item><el-form-item label="单位"><el-select v-model="ruleForm.movementUnit"><el-option label="百分比 %" value="percent"/><el-option label="金额 USDT" value="amount"/></el-select></el-form-item><el-form-item label="达到幅度"><el-input-number v-model="ruleForm.threshold" :min="0.000001" :controls="false"/></el-form-item></div><p class="hint">{{ conditionText(ruleForm) }}</p></el-form><template #footer><el-button @click="ruleDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveRule">保存规则</el-button></template></el-dialog>
    <el-dialog v-model="templateDialog" title="新建推送模板" width="580px"><el-form label-position="top"><div class="form-grid"><el-form-item label="模板名称" required><el-input v-model="templateForm.name"/></el-form-item><el-form-item label="消息类型"><el-select v-model="templateForm.messageType"><el-option label="文本消息" value="text"/><el-option label="消息卡片" value="card"/></el-select></el-form-item></div><el-form-item label="标题" required><el-input v-model="templateForm.title"/></el-form-item><el-form-item label="内容" required><el-input v-model="templateForm.content" type="textarea" :rows="5"/></el-form-item><p class="hint">可用变量：symbol、current_value、threshold、triggered_at、event_type、baseline_value、movement_amount、movement_percent、window_minutes，用双花括号包裹。</p></el-form><template #footer><el-button @click="templateDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveTemplate">保存模板</el-button></template></el-dialog>
    <el-dialog v-model="eventsDialog" :title="`${eventsTaskName} · 推送记录`" width="640px"><el-table :data="selectedEvents" empty-text="暂无推送记录"><el-table-column label="时间" min-width="165"><template #default="{row}">{{ formatTime(row.createdAt) }}</template></el-table-column><el-table-column label="事件" width="85"><template #default="{row}">{{ row.eventType==='recovery'?'恢复':row.eventType==='report'?'汇报':'触发' }}</template></el-table-column><el-table-column prop="value" label="当前值" width="110"/><el-table-column label="发送结果" min-width="140"><template #default="{row}"><span :class="row.success?'success':'error'">{{ row.success?'成功':row.error||'失败' }}</span></template></el-table-column></el-table></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { dataMonitorApi, type MonitorEvent, type MonitorMetric, type MonitorOperator, type MonitorRule, type MonitorRuleType, type MonitorTask, type MonitorTaskPayload, type MonitorTemplate } from '@/api/dataMonitor'
import { messagePushApi, type MessagePushConfig } from '@/api/messagePush'
import { marketApi } from '@/api/market'

const tab=ref('tasks'), keyword=ref(''), status=ref('all'), loading=ref(false), saving=ref(false), togglingId=ref('')
const tasks=ref<MonitorTask[]>([]), rules=ref<MonitorRule[]>([]), templates=ref<MonitorTemplate[]>([]), channels=ref<MessagePushConfig[]>([])
const summary=ref<{todayTriggers:number;pushSuccessRate:number|null}>({todayTriggers:0,pushSuccessRate:null})
const symbols=ref(['BTC-USDT','ETH-USDT','SOL-USDT']), symbolLoading=ref(false)
const taskDrawer=ref(false), ruleDialog=ref(false), templateDialog=ref(false), eventsDialog=ref(false)
const editingId=ref<string|null>(null), step=ref(1), selectedEvents=ref<MonitorEvent[]>([]), eventsTaskName=ref('')
let timer: ReturnType<typeof setInterval>|undefined
const ruleTypeOptions=[{label:'阈值触发',value:'threshold'},{label:'定时汇报',value:'scheduled'},{label:'区间浮动',value:'movement'}]
const defaultOptions=()=>({ruleType:'threshold' as MonitorRuleType,windowMinutes:60,movementUnit:'percent' as const,movementDirection:'either' as const,startTime:'09:00',endTime:'18:00',reportIntervalMinutes:60})
const emptyForm=():MonitorTaskPayload=>({name:'',exchange:'OKX',symbol:'BTC-USDT',frequencySeconds:60,ruleId:'preset-price-high',metric:'price',operator:'>',threshold:70000,...defaultOptions(),pushConfigId:'',templateId:'preset-standard',cooldownSeconds:900,recoveryNotice:true,enabled:true})
const form=reactive<MonitorTaskPayload>(emptyForm())
const ruleForm=reactive({name:'',description:'',metric:'price' as MonitorMetric,operator:'>' as MonitorOperator,threshold:0,...defaultOptions()})
watch(()=>form.ruleType,type=>{if(type!=='threshold'){form.metric='price';if(type==='movement'&&form.threshold<=0)form.threshold=3;if(type==='scheduled')form.templateId='preset-report';else if(form.templateId==='preset-report')form.templateId='preset-movement'}})
watch(()=>ruleForm.ruleType,type=>{if(type!=='threshold'){ruleForm.metric='price';if(type==='movement'&&ruleForm.threshold<=0)ruleForm.threshold=3}})
const templateForm=reactive({name:'',messageType:'text' as 'text'|'card',title:'{{symbol}} 监控提醒',content:'{{symbol}} 的 {{metric}} 当前值 {{current_value}}，阈值 {{threshold}}。'})
const enabledChannels=computed(()=>channels.value.filter(x=>x.enabled))
const todayCount=computed(()=>summary.value.todayTriggers)
const successRate=computed(()=>summary.value.pushSuccessRate===null?'—':`${summary.value.pushSuccessRate}%`)
const filteredTasks=computed(()=>tasks.value.filter(x=>(!keyword.value||`${x.name} ${x.symbol}`.toLowerCase().includes(keyword.value.toLowerCase()))&&(status.value==='all'||x.enabled===(status.value==='running'))))
const metricName=(m:MonitorMetric)=>({price:'最新价格',change:'24h 涨跌幅',volume:'24h 成交额',rsi:'RSI(14)'})[m]
const operatorName=(o:MonitorOperator)=>({'>':'大于','<':'小于',cross_up:'向上穿越',cross_down:'向下穿越'})[o]
const formatValue=(v:number,m:MonitorMetric)=>`${Number(v).toLocaleString('zh-CN',{maximumFractionDigits:4})}${m==='change'?'%':m==='price'||m==='volume'?' USDT':''}`
const conditionText=(x:Pick<MonitorTaskPayload,'ruleType'|'metric'|'operator'|'threshold'|'startTime'|'endTime'|'reportIntervalMinutes'|'windowMinutes'|'movementDirection'|'movementUnit'>)=>x.ruleType==='scheduled'?`每日 ${x.startTime||'—'}–${x.endTime||'—'}，每 ${x.reportIntervalMinutes||'—'} 分钟汇报`:x.ruleType==='movement'?`${x.windowMinutes||'—'} 分钟内${({either:'涨跌',up:'上涨',down:'下跌'} as Record<string,string>)[x.movementDirection||'either']} ≥ ${x.threshold}${x.movementUnit==='percent'?'%':' USDT'}`:`${metricName(x.metric)} ${operatorName(x.operator)} ${formatValue(x.threshold,x.metric)}`
const thresholdValid=(metric:MonitorMetric,value:number)=>Number.isFinite(value)&&(metric==='rsi'?value>=0&&value<=100:metric==='price'||metric==='volume'?value>0:true)
const ruleValid=(x:typeof ruleForm|MonitorTaskPayload)=>x.ruleType==='scheduled'?!!x.startTime&&!!x.endTime&&x.startTime!==x.endTime&&!!x.reportIntervalMinutes&&x.reportIntervalMinutes>=1:x.ruleType==='movement'?!!x.windowMinutes&&x.windowMinutes>=1&&!!x.movementUnit&&!!x.movementDirection&&Number.isFinite(x.threshold)&&x.threshold>0:thresholdValid(x.metric,x.threshold)
const formatTime=(v:string|null)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'尚未触发'
async function loadTasks(){loading.value=true;try{const [t,s]=await Promise.all([dataMonitorApi.tasks(),dataMonitorApi.summary()]);tasks.value=t.list;summary.value=s}finally{loading.value=false}}
async function loadOptions(){const [r,t,c]=await Promise.all([dataMonitorApi.rules(),dataMonitorApi.templates(),messagePushApi.getList()]);rules.value=r.list;templates.value=t.list;channels.value=c.list}
async function refresh(){try{await Promise.all([loadTasks(),loadOptions()])}catch{/* request client displays errors */}}
async function searchSymbols(q:string){if(!q.trim())return;symbolLoading.value=true;try{const r=await marketApi.searchSymbols(q);symbols.value=[...new Set([form.symbol,...r.list.map(x=>x.symbol)])].slice(0,50)}catch{/* keep current options */}finally{symbolLoading.value=false}}
function openCreate(){Object.assign(form,emptyForm(),{pushConfigId:enabledChannels.value[0]?.id||'',templateId:templates.value[0]?.id||'preset-standard'});editingId.value=null;step.value=1;taskDrawer.value=true}
function openEdit(x:MonitorTask){Object.assign(form,{name:x.name,exchange:x.exchange,symbol:x.symbol,frequencySeconds:x.frequencySeconds,ruleId:x.ruleId,metric:x.metric,operator:x.operator,threshold:x.threshold,ruleType:x.ruleType,windowMinutes:x.windowMinutes,movementUnit:x.movementUnit,movementDirection:x.movementDirection,startTime:x.startTime,endTime:x.endTime,reportIntervalMinutes:x.reportIntervalMinutes,pushConfigId:x.pushConfigId,templateId:x.templateId,cooldownSeconds:x.cooldownSeconds,recoveryNotice:x.recoveryNotice,enabled:x.enabled});symbols.value=[...new Set([x.symbol,...symbols.value])];editingId.value=x.id;step.value=1;taskDrawer.value=true;if(x.lastError)ElMessage.warning(`最近一次检测失败：${x.lastError}`)}
function selectRule(x:MonitorRule){Object.assign(form,{ruleId:x.id,metric:x.metric,operator:x.operator,threshold:x.threshold,ruleType:x.ruleType,windowMinutes:x.windowMinutes??60,movementUnit:x.movementUnit??'percent',movementDirection:x.movementDirection??'either',startTime:x.startTime??'09:00',endTime:x.endTime??'18:00',reportIntervalMinutes:x.reportIntervalMinutes??60});if(form.templateId==='preset-standard'||form.templateId==='preset-simple')form.templateId=x.ruleType==='scheduled'?'preset-report':x.ruleType==='movement'?'preset-movement':'preset-standard'}
function useRule(x:MonitorRule){openCreate();selectRule(x);ElMessage.info(`已选用「${x.name}」，请先填写任务名称`)}
function nextStep(){if(step.value===1&&(!form.name.trim()||!form.symbol))return ElMessage.warning('请填写任务名称和交易对象');if(step.value===2&&!ruleValid(form))return ElMessage.warning('请填写有效的规则条件');if(step.value===2&&form.ruleType==='scheduled'&&form.reportIntervalMinutes!*60<form.frequencySeconds)return ElMessage.warning('检测频率不能低于汇报间隔');if(step.value===2&&form.ruleType==='movement'&&form.windowMinutes!*60<form.frequencySeconds)return ElMessage.warning('检测频率不能低于价格浮动窗口');if(step.value<3){step.value++;return}void saveTask()}
async function saveTask(){if(!form.pushConfigId||!form.templateId)return ElMessage.warning('请选择推送渠道和消息模板');saving.value=true;try{if(editingId.value)await dataMonitorApi.updateTask(editingId.value,{...form});else await dataMonitorApi.createTask({...form});taskDrawer.value=false;ElMessage.success(editingId.value?'任务已更新':'任务已创建');await loadTasks()}finally{saving.value=false}}
async function toggleTask(x:MonitorTask,enabled:boolean){togglingId.value=x.id;try{await dataMonitorApi.setEnabled(x.id,enabled);x.enabled=enabled}finally{togglingId.value=''}}
async function duplicateTask(x:MonitorTask){await dataMonitorApi.createTask({name:`${x.name}（副本）`,exchange:x.exchange,symbol:x.symbol,frequencySeconds:x.frequencySeconds,ruleId:x.ruleId,metric:x.metric,operator:x.operator,threshold:x.threshold,ruleType:x.ruleType,windowMinutes:x.windowMinutes,movementUnit:x.movementUnit,movementDirection:x.movementDirection,startTime:x.startTime,endTime:x.endTime,reportIntervalMinutes:x.reportIntervalMinutes,pushConfigId:x.pushConfigId,templateId:x.templateId,cooldownSeconds:x.cooldownSeconds,recoveryNotice:x.recoveryNotice,enabled:false});ElMessage.success('任务已复制');await loadTasks()}
async function removeTask(x:MonitorTask){await ElMessageBox.confirm(`确定删除「${x.name}」？`,'删除监控任务',{type:'warning'});await dataMonitorApi.deleteTask(x.id);await loadTasks()}
async function showEvents(x:MonitorTask){eventsTaskName.value=x.name;selectedEvents.value=(await dataMonitorApi.events(x.id)).list;eventsDialog.value=true}
async function saveRule(){if(!ruleForm.name.trim())return ElMessage.warning('请输入规则名称');if(!ruleValid(ruleForm))return ElMessage.warning('请填写有效的规则条件');saving.value=true;try{await dataMonitorApi.createRule({...ruleForm});ruleDialog.value=false;await loadOptions()}finally{saving.value=false}}
async function removeRule(x:MonitorRule){await ElMessageBox.confirm(`确定删除「${x.name}」？`,'删除规则',{type:'warning'});await dataMonitorApi.deleteRule(x.id);await loadOptions()}
async function saveTemplate(){if(!templateForm.name.trim()||!templateForm.title.trim()||!templateForm.content.trim())return ElMessage.warning('请填写完整模板');saving.value=true;try{await dataMonitorApi.createTemplate({...templateForm});templateDialog.value=false;await loadOptions()}finally{saving.value=false}}
async function removeTemplate(x:MonitorTemplate){await ElMessageBox.confirm(`确定删除「${x.name}」？`,'删除模板',{type:'warning'});await dataMonitorApi.deleteTemplate(x.id);await loadOptions()}
onMounted(()=>{void refresh();timer=setInterval(()=>{if(!taskDrawer.value&&!document.hidden)void loadTasks().catch(()=>{})},10000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>

