op:1px solid #eef1f4}.summary dt{color:#94a3b8}.summary dd{margin:0;text-align:right;overflow-wrap:anywhere}.drawer-actions{display:flex;justify-content:space-between;gap:12px}.notice{margin:-7px 0 16px;color:#a36a27;font-size:11px}.hint{color:#94a3b8;font-size:11px}.success{color:#16803d}.error{color:#d14343}@media(max-width:1100px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.rules{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.heading,.section-head,.toolbar{align-items:stretch;flex-direction:column}.stats,.rules,.templates,.form-grid,.form-grid.three,.rule-picks{grid-template-columns:1fr}.filters{flex-direction:column}.filters :deep(.el-input),.filters :deep(.el-select){width:100%!important}.panel{overflow:hidden}}
